def sift_down(a, i):
    n = len(a); value = a[i]                  # hole-punching: one write per level
    while True:
        l, r = 2*i + 1, 2*i + 2
        if l >= n: break
        c = l if (r >= n or a[l] <= a[r]) else r   # the SMALLER child in a min-heap
        if a[c] >= value: break
        a[i] = a[c]; i = c
    a[i] = value

def heapify(a):
    for i in range(len(a)//2 - 1, -1, -1):     # last internal node down to root: Theta(n)
        sift_down(a, i)

def push(a, v):
    a.append(v); i = len(a) - 1
    while i > 0:                              # guard BEFORE computing (i-1)//2
        p = (i - 1) // 2
        if a[p] <= a[i]: break
        a[p], a[i] = a[i], a[p]; i = p

def pop(a):
    top = a[0]; a[0] = a[-1]; a.pop()
    if a: sift_down(a, 0)
    return top
